#include <stdlib.h>
static int gcd(int a,int b){if(a<0)a=-a;if(b<0)b=-b;while(b){int t=a%b;a=b;b=t;}return a;}typedef struct{int dx,dy,c;}Slope;int maxPoints(int**p,int n,int*cols){if(n<3)return n;int best=0;for(int i=0;i<n;i++){Slope*a=malloc(n*sizeof(Slope));int m=0,dup=1,local=0;for(int j=i+1;j<n;j++){int dx=p[j][0]-p[i][0],dy=p[j][1]-p[i][1];if(!dx&&!dy){dup++;continue;}int g=gcd(dx,dy);dx/=g;dy/=g;if(dx<0||(dx==0&&dy<0)){dx=-dx;dy=-dy;}int k;for(k=0;k<m;k++)if(a[k].dx==dx&&a[k].dy==dy){a[k].c++;break;}if(k==m)a[m++]=(Slope){dx,dy,1};}for(int k=0;k<m;k++)if(a[k].c>local)local=a[k].c;if(local+dup>best)best=local+dup;free(a);}return best;}
